// ─── PRICE CALCULATOR ─────────────────────────────────────────────
function calcPrice(sel) {
  const { service, size, coat, mattingAreas, addons } = sel;
  if (!service || !size) return null;

  const base = PRICES.services[service][size];

  let fixedAdds = 0;
  let rangeMin  = 0;
  let rangeMax  = 0;

  if (addons.teeth)    fixedAdds += PRICES.teeth;
  if (addons.hydra)    fixedAdds += PRICES.hydra[size];
  if (addons.shedless) fixedAdds += PRICES.shedless[size];
  if (addons.medicated){  rangeMin += PRICES.medicated[0];  rangeMax += PRICES.medicated[1]; }
  if (addons.flea)     {  rangeMin += PRICES.fleaShampoo[0];rangeMax += PRICES.fleaShampoo[1]; }
  if (addons.blueberry){  rangeMin += PRICES.blueberry[0];  rangeMax += PRICES.blueberry[1]; }

  const demat = coat!=="none"&&mattingAreas ? PRICES.dematting[mattingAreas] : null;
  const demMin = demat?.[0] ?? 0;
  const demMax = demat?.[1] ?? 0;

  const min = base + fixedAdds + rangeMin + demMin;
  const max = base + fixedAdds + rangeMax + demMax;

  return { min, max, base, fixedAdds, rangeMin, rangeMax, demat, size };
}

function fmtPrice(min, max) {
  return min === max ? `$${min}` : `$${min}-$${max}`;
}

